function clean(v){return String(v??'').normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function setKey(r){return [r.year,r.brand,r.set].map(clean).join('|')}
function refKey(r){return [r.year,r.brand,r.set,r.number,r.player,r.parallel].map(clean).join('|')}
