function completion(refs,inventory){const owned=new Set(inventory.filter(c=>c.number&&c.year&&c.set).map(refKey));const unique=[...new Map(refs.map(r=>[refKey(r),r])).values()];return {total:unique.length,matched:unique.filter(r=>r.number&&r.year&&r.set&&owned.has(refKey(r))).length,missing:unique.filter(r=>!r.number||!r.year||!r.set||!owned.has(refKey(r)))}}
