async function visionIdentify(single=false){if(scanBusy||!scanItems.length)return scanMessage('Detect at least one card first.');let url;try{url=new URL($('visionEndpoint').value);if(url.protocol!=='https:')throw Error()}catch{return scanMessage('Enter a valid HTTPS endpoint.')}const key=$('visionKey').value.trim();if(!key)return scanMessage('Enter your private Worker access key.');const batch=scanItems.filter(x=>!x.approved);if(single)batch.splice(1);stopRequested21=false;if(!batch.length)return scanMessage('No unapproved crops.');if(!confirm(`Send ${batch.length} cropped images to ${url.origin}?`))return;scanBusy=true;let ok=0,failed=0;try{for(const x of batch){if(stopRequested21)break;scanMessage(`AI identification ${ok+failed+1}/${batch.length}`);const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),45000);try{const res=await fetch(url.href,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({image:x.photo,ocr:x.ocr,focus:$('refFocus').value?$('refFocus').selectedOptions[0].textContent:''}),signal:ctl.signal});if(!res.ok){const detail=await res.json().catch(()=>({}));throw Error('HTTP '+res.status+(detail.error?' — '+String(detail.error).slice(0,180):''));}const r=await res.json();if(typeof r.player!=='string'||!r.player.trim())throw Error('No readable identity returned');for(const k of scanKeys)if(typeof r[k]==='string'&&r[k].trim()&&!x[k])x[k]=r[k].trim().slice(0,160);x.approved=false;x.visionEvidence={player:r.player||'',year:r.year||'',brand:r.brand||'',set:r.set||'',number:r.number||'',parallel:r.parallel||''};delete x.aiError;queueDraft();ok++}catch(e){failed++;x.aiError=e.message;if(/HTTP (401|403|429|502|503)/.test(e.message))break}finally{clearTimeout(timer)}}scanMessage(`${ok} suggestions; ${failed} failed; ${batch.length-ok-failed} not processed. ${batch.find(x=>x.aiError)?.aiError||'Confirm every identity.'}`)}finally{scanBusy=false;renderScan()}}
