function updateReviewCount(){const e=$('scanReviewCount');if(e)e.textContent=`${scanItems.filter(x=>x.approved&&x.player.trim()).length} of ${scanItems.length} ready to import`;}
function strongSuggestion(x,refs,focus){const n=clean([x.ocr,x.player,x.set,x.number,x.parallel].join(' '));const ranked=refs.filter(r=>(!focus||setKey(r)===focus)&&['player','year','brand','set','number','parallel'].every(k=>!x[k]||clean(x[k])===clean(r[k]))).map(r=>({r,score:matchScore(n,r)})).sort((a,b)=>b.score-a.score);const a=ranked[0];if(!a||a.score<12||a.score-(ranked[1]?.score||0)<4||!a.r.number||!a.r.year||!a.r.set||!a.r.brand)return null;const p=clean(a.r.player);if(!(' '+n+' ').includes(' '+p+' '))return null;return a.r;}
$('suggestBatch').onclick=()=>{if(scanBusy)return;let count=0;for(const x of scanItems){if(x.approved)continue;const r=strongSuggestion(x,scanRefs,$('refFocus').value);if(!r)continue;for(const k of scanKeys)if(k!=='serial'&&k!=='parallel'&&!x[k]&&r[k])x[k]=r[k];x.approved=false;count++}renderScan();scanMessage(`${count} strong candidates filled. All still require review; verify parallel and card number.`)};
