$('visionTest').onclick=async()=>{if(scanBusy)return;let u;try{u=new URL($('visionEndpoint').value);if(u.protocol!=='https:')throw Error('HTTPS required');scanBusy=true;const r=await fetch(u.href,{method:'GET',signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();if(j.status!=='ok')throw Error('Unexpected health response');scanMessage('Endpoint reachable. Image recognition and AI quota not tested.')}catch(e){scanMessage('Connection test failed: '+e.message)}finally{scanBusy=false}};

function marketIdentity(c){return JSON.stringify(['player','year','brand','set','number','parallel','grade','serial'].map(k=>String(c[k]??'').trim().toLowerCase()))}
function marketStats(rows,now=Date.now()){const seen=new Set();for(const r of rows){const u=new URL(r.url);const key=/^(www\.)?ebay\.com$/i.test(u.hostname)&&u.pathname.match(/\/itm\/(?:[^/]+\/)?(\d+)/)?'ebay:'+u.pathname.match(/\/itm\/(?:[^/]+\/)?(\d+)/)[1]:u.origin+u.pathname;if(u.protocol!=='https:'||seen.has(key)||r.confirmed!=='yes'||!Number.isFinite(r.price)||r.price<=0||!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!Number.isFinite(Date.parse(r.date))||new Date(r.date).toISOString().slice(0,10)!==r.date||Date.parse(r.date)>now||now-Date.parse(r.date)>90*86400000)throw Error('Invalid, duplicate, unconfirmed or non-recent sale');seen.add(key)}if(!rows.length)throw Error('No sales');const a=rows.map(r=>r.price).sort((a,b)=>a-b),n=a.length,round=x=>Math.round(x*100)/100;return {average:round(a.reduce((x,y)=>x+y,0)/n),median:round((a[Math.floor((n-1)/2)]+a[Math.floor(n/2)])/2),count:n,min:a[0],max:a[n-1],confidence:n>=3?'Moderate':'Low',asOf:new Date(now).toISOString(),sales:rows.map(({price,date,url})=>({price,date,url}))}}
let marketLimit=20,marketPending=[];function marketList(){return cards.filter(c=>$('marketQueue').value==='all'||($('marketQueue').value==='unpriced'?!known(c):!c.valuation||!Number.isFinite(Date.parse(c.valuation.asOf))||Date.now()-Date.parse(c.valuation.asOf)>90*86400000))}function marketRender(){const list=marketList();$('marketCount').textContent=list.length+' matching entries';$('marketRows').replaceChildren();for(const c of list.slice(0,marketLimit)){const el=document.createElement('div');el.className='panel';const title=document.createElement('b');title.textContent=[c.player,c.year,c.set,c.number,c.parallel,c.grade].filter(Boolean).join(' · ');const info=document.createElement('p');info.textContent=(known(c)?money(c.value):'Unpriced')+' · '+(c.valueSource||'No source');const link=document.createElement('a');link.href=compUrl(c);link.target='_blank';link.rel='noopener';link.textContent='Sold listings';const btn=document.createElement('button');btn.textContent='Review card';btn.onclick=()=>{$('marketDialog').close();editCard(c.id)};el.append(title,info,link,btn);$('marketRows').append(el)}$('marketNext').hidden=list.length<=marketLimit}
$('marketOpen').onclick=()=>{marketLimit=20;marketRender();$('marketDialog').showModal()};$('marketClose').onclick=()=>$('marketDialog').close();$('marketQueue').onchange=()=>{marketLimit=20;marketRender()};$('marketNext').onclick=()=>{marketLimit+=20;marketRender()};const marketColumns=['id','identity','player','sale_price_usd','sale_date','sale_url','exact_match_confirmed'];$('marketExport').onclick=()=>{const q=v=>'"'+String(v??'').replaceAll('"','""')+'"';download('card-vault-market-worksheet.csv',[marketColumns.join(','),...marketList().map(c=>[c.id,marketIdentity(c),c.player,'','','',''].map(q).join(','))].join('\n'),'text/csv')};function marketParse(raw,inventory){const rows=parseCSV(raw),head=rows.shift().map(x=>x.replace(/^\uFEFF/,'').trim());if(marketColumns.some(k=>!head.includes(k)))throw Error('Use the exported worksheet columns');const groups=new Map();for(const row of rows){const r=Object.fromEntries(head.map((k,i)=>[k,(row[i]||'').trim()]));if(!r.sale_price_usd&&!r.sale_date&&!r.sale_url)continue;const c=inventory.find(x=>x.id===r.id);if(!c||marketIdentity(c)!==r.identity)throw Error('Missing or changed card: '+r.id);if(!c.player||!c.year||!c.set||!c.number||!c.grade)throw Error('Complete identity and grade for '+c.player);if(!groups.has(c.id))groups.set(c.id,{c,rows:[]});groups.get(c.id).rows.push({price:Number(r.sale_price_usd),date:r.sale_date,url:r.sale_url,confirmed:r.exact_match_confirmed.toLowerCase()})}return [...groups.values()].map(({c,rows})=>({id:c.id,identity:marketIdentity(c),valuation:marketStats(rows)}))}
$('marketFile').onchange=async()=>{marketPending=[];$('marketCommit').disabled=true;try{marketPending=marketParse(await $('marketFile').files[0].text(),cards);$('marketReport').textContent=marketPending.length+' cards ready: '+marketPending.slice(0,10).map(x=>cards.find(c=>c.id===x.id).player+' '+money(x.valuation.average)).join('; ');$('marketCommit').disabled=!marketPending.length}catch(e){$('marketReport').textContent=e.message}};$('marketCommit').onclick=async()=>{try{const current=await readAll();const updates=marketPending.map(x=>{const c=current.find(c=>c.id===x.id);if(!c||marketIdentity(c)!==x.identity)throw Error('Card changed; reimport worksheet');return {...c,value:x.valuation.average,valuation:x.valuation,valueSource:'User-reviewed sold comps',updated:Date.now()}});if(!updates.length||!confirm('Apply average sold prices to '+updates.length+' cards? Existing estimates will be replaced.'))return;await tx('readwrite',s=>updates.forEach(c=>s.put(c)));marketPending=[];$('marketCommit').disabled=true;$('marketReport').textContent='Saved '+updates.length+' valuations';await refresh();marketRender()}catch(e){$('marketReport').textContent=e.message}};

// v1.8 scenario analysis; no external pricing or grade predictions.
function gradeMath(v){const {raw,high,low,chance,cost,fee,ship}=v;if(!Object.values(v).every(Number.isFinite)||[raw,high,low,cost,ship].some(x=>x<0)||chance<0||chance>100||fee<0||fee>=100||high<low)throw Error('Enter valid nonnegative amounts, probabilities and fees; target value must be at least lower-grade value.');const f=1-fee/100,p=chance/100,net=x=>x*f-ship;const rawNet=net(raw),highNet=net(high)-cost,lowNet=net(low)-cost,expected=p*highNet+(1-p)*lowNet;return {rawNet,highNet,lowNet,expected,increment:expected-rawNet,breakEven:raw+cost/f,requiredChance:high===low?null:100*(raw+cost/f-low)/(high-low)}}
const gradeFields=['Raw','High','Low','Chance','Cost','Fee','Ship'];let gradeCard=null;
function gradeRead(){return Object.fromEntries(gradeFields.map(k=>[k.toLowerCase(),$('grade'+k).value.trim()===''?NaN:Number($('grade'+k).value)]))}
function gradeDecision(c,m){if($('gradeProtect').checked)return 'KEEP — personal collection';if(!c||!c.player||!c.year||!c.set||!c.number||!$('gradeEvidence').checked)return 'RESEARCH — confirm identity and sold comps';if(!/^raw$/i.test(String(c.grade||'').trim()))return 'SELL / HOLD — existing slab or unknown grade; grading scenario not recommended';return m.increment>0&&m.lowNet>=m.rawNet?'GRADE — favorable even in lower-grade scenario':m.increment>0?'RESEARCH — positive expected upside, but downside risk':'SELL / HOLD — grading does not improve expected proceeds'}
function gradeUpdate(){const c=gradeCard;if(!c)return;const company=$('gradeCompany').value,target=$('gradeTarget').value;$('gradeRawLink').href=compUrl({...c,grade:/^raw$/i.test(c.grade||'')?'RAW':c.grade});$('gradeSlabLink').href=compUrl({...c,grade:company+' '+target});try{const m=gradeMath(gradeRead());$('gradeResult').textContent=gradeDecision(c,m)+' | Current sale net '+money(m.rawNet)+' | Target net '+money(m.highNet)+' | Lower-grade net '+money(m.lowNet)+' | Expected graded net '+money(m.expected)+' | Increment vs current sale '+money(m.increment)+' | Break-even graded sale '+money(m.breakEven)+(m.requiredChance===null?'':' | Required target chance '+(m.requiredChance<=0?'0%':m.requiredChance>100?'Not achievable':m.requiredChance.toFixed(1)+'%'));}catch(e){$('gradeResult').textContent=$('gradeProtect').checked?'KEEP — personal collection. '+e.message:'RESEARCH — '+e.message}}
function gradeSelect(){gradeCard=cards.find(c=>c.id===$('gradePick').value)||null;const c=gradeCard;$('gradeSave').disabled=!c;$('gradeEdit').disabled=!c;if(!c){$('gradeSummary').textContent='No matching cards';$('gradeResult').textContent='';$('gradeRawLink').removeAttribute('href');$('gradeSlabLink').removeAttribute('href');return}const d=c.resalePlan&&c.resalePlan.identity===marketIdentity(c)?c.resalePlan:null;$('gradeSummary').textContent=[c.player,c.year,c.set,c.number,c.grade,c.valueSource,d?'Saved: '+d.decision:''].filter(Boolean).join(' · ');const defaults={Raw:known(c)?c.value:'',High:'',Low:'',Chance:50,Cost:25,Fee:15,Ship:5};for(const k of gradeFields)$('grade'+k).value=d?.inputs?.[k.toLowerCase()]??defaults[k];$('gradeCompany').value=d?.company||'CGC';$('gradeTarget').value=d?.target||'9';$('gradeProtect').checked=d?.protect??!!c.favorite;$('gradeEvidence').checked=false;gradeUpdate()}
function gradeList(){const q=norm($('gradeSearch').value),old=$('gradePick').value;const list=cards.filter(c=>norm([c.player,c.set,c.year,c.number].join(' ')).includes(q)).sort((a,b)=>(Number(b.value)||0)-(Number(a.value)||0));$('gradePick').replaceChildren(...list.map(c=>{const o=document.createElement('option');o.value=c.id;o.textContent=[c.player,c.year,c.set,c.number,known(c)?money(c.value):'Unpriced'].filter(Boolean).join(' · ');return o}));if(list.some(c=>c.id===old))$('gradePick').value=old;gradeSelect()}
$('gradeOpen').onclick=()=>{ $('gradeSearch').value='';gradeList();$('gradeDialog').showModal()};$('gradeClose').onclick=()=>$('gradeDialog').close();$('gradeSearch').oninput=gradeList;$('gradePick').onchange=gradeSelect;for(const k of [...gradeFields,'Company','Target','Protect','Evidence'])$('grade'+k).oninput=gradeUpdate;$('gradeEdit').onclick=()=>{if(gradeCard){$('gradeDialog').close();editCard(gradeCard.id)}};$('gradeSave').onclick=async()=>{try{if(!gradeCard)return;const inputs=gradeRead(),m=gradeMath(inputs),decision=gradeDecision(gradeCard,m),current=(await readAll()).find(c=>c.id===gradeCard.id);if(!current||marketIdentity(current)!==marketIdentity(gradeCard))throw Error('Card changed; reopen planner');const resalePlan={identity:marketIdentity(current),inputs,company:$('gradeCompany').value,target:$('gradeTarget').value,protect:$('gradeProtect').checked,evidence:$('gradeEvidence').checked,decision,asOf:new Date().toISOString()};await tx('readwrite',s=>s.put({...current,resalePlan}));await refresh();gradeCard=cards.find(c=>c.id===current.id);$('gradeSummary').textContent='Saved: '+decision}catch(e){alert(e.message)}};

function validateBackup(data){if(!data||data.app!=='The Card Vault'||!Array.isArray(data.cards))throw Error('Not a valid Card Vault backup');const ids=new Set();for(const c of data.cards){if(!c||typeof c.id!=='string'||!c.id.trim()||typeof c.player!=='string'||!c.player.trim()||ids.has(c.id))throw Error('Invalid record or duplicate ID; inventory unchanged');ids.add(c.id);if(c.quantity!=null&&(typeof c.quantity==='boolean'||!Number.isInteger(Number(c.quantity))||Number(c.quantity)<1))throw Error('Invalid quantity');if(c.value!=null&&c.value!==''&&(typeof c.value==='boolean'||!Number.isFinite(Number(c.value))||Number(c.value)<0))throw Error('Invalid value')}return ids.size}
$('healthCheck').onclick=async()=>{const out=$('healthReport');try{const current=await readAll();validateBackup({app:'The Card Vault',cards:current});out.textContent=['Inventory: '+current.length+' records','Record integrity: passed','Unpriced: '+current.filter(c=>!known(c)).length,'Checklist references: '+scanRefs.length+' (may be partial)','AI endpoint: '+($('visionEndpoint').value.trim()?'Entered; live test required':'Not configured'),'Automatic sold-price feed: not connected','Offline worker: '+(navigator.serviceWorker?.controller?'Active':'Not controlling page yet')].join('\n')}catch(e){out.textContent='Check failed: '+e.message}};

$('reviewPrev').onclick=()=>{if(!scanBusy){reviewPage=Math.max(0,reviewPage-1);renderScan()}};$('reviewNext').onclick=()=>{if(!scanBusy){reviewPage++;renderScan()}};
let draftTimer;function draftDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('card-vault-scan-draft',1);r.onupgradeneeded=()=>r.result.createObjectStore('draft');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}function queueDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(saveDraft,350)}async function saveDraft(){try{const d=await draftDB(),t=d.transaction('draft','readwrite');t.objectStore('draft').put({image:scanImage?scanImage.toDataURL('image/jpeg',.8):null,items:scanItems},'current');t.oncomplete=()=>{d.close();$('draftStatus').textContent='Scan draft saved locally'};t.onerror=()=>{d.close();$('draftStatus').textContent='Draft save failed'}}catch(e){$('draftStatus').textContent='Draft unavailable'}}
$('draftResume').onclick=async()=>{if(scanBusy||scanItems.length&&!confirm('Replace current scan with saved draft?'))return;try{const d=await draftDB();const v=await new Promise((resolve,reject)=>{const r=d.transaction('draft').objectStore('draft').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});d.close();if(!v?.image)return scanMessage('No saved scan draft');const im=new Image();im.src=v.image;await im.decode();const c=document.createElement('canvas');c.width=sc.width=im.width;c.height=sc.height=im.height;c.getContext('2d').drawImage(im,0,0);scanImage=c;scanItems=v.items||[];scanArea=null;reviewPage=0;drawScan();renderScan();scanMessage('Draft restored. Review before importing.')}catch(e){scanMessage('Could not restore draft: '+e.message)}};

// v2.6: conservative exact-match automation and durable exception review.
let stopRequested21=false, lastBatch21=null, detected21=0;
function identity21(x){return ['player','year','brand','set','number','parallel','serial'].map(k=>clean(x[k])).join('|')}
function exact21(x,refs){
 const required=['player','year','brand','set','number','parallel'];
 if(!required.every(k=>typeof x[k]==='string'&&x[k].trim())||x.serial||!x.ocr)return null;
 // Explicit variation evidence is required; blank/base-only checklists cannot prove a parallel.
 const text=' '+clean(x.ocr)+' ';
 if(!required.every(k=>text.includes(' '+clean(x[k])+' ')))return null;
 if(!new RegExp('(?:card\\s*(?:no\\.?|number|#)\\s*|#\\s*)'+x.number.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?:\\b|$)','i').test(x.ocr))return null;
 const matches=refs.filter(r=>required.every(k=>clean(r[k])===clean(x[k]))&&r.source);
 return matches.length===1?matches[0]:null;
}
function summary21(){const e=$('summary21');if(!e)return;const added=lastBatch21?.ids.length||0;e.textContent=`${detected21||scanItems.length} detected in current scan · ${added} added in last import · ${scanItems.length} awaiting review · ${scanItems.filter(x=>!x.player).length} unidentified`;}
function timeout21(p,ms,label){let t;return Promise.race([p,new Promise((_,reject)=>{t=setTimeout(()=>reject(Error(label)),ms)})]).finally(()=>clearTimeout(t))}
async function rotate21(photo,turn){const im=new Image();im.src=photo;await im.decode();const c=document.createElement('canvas');c.width=Math.abs(turn)%2?im.height:im.width;c.height=Math.abs(turn)%2?im.width:im.height;const g=c.getContext('2d');g.translate(c.width/2,c.height/2);g.rotate(turn*Math.PI/2);g.drawImage(im,-im.width/2,-im.height/2);return c.toDataURL('image/jpeg',.85)}
async function import21(items,automatic){if(!items.length){scanMessage('No approved cards with a player name.');return {added:0,duplicates:0};}const ownBusy=!scanBusy;if(ownBusy)scanBusy=true;try{const current=await readAll(),seen=new Set(current.map(identity21)),records=[],accepted=[],batch=uid();for(const x of items){if(!x.player?.trim())continue;const key=identity21(x);if(seen.has(key)){x.aiError='Possible duplicate — review in collection';continue}seen.add(key);x.scanId=x.scanId||uid();const id='scan-'+x.scanId;if(current.some(c=>c.id===id))continue;const c={id,photo:x.photo,quantity:1,value:null,cost:0,grade:'RAW',source:automatic?'Scan — exact reference match':'Scan — user reviewed',scanBatch:batch,updated:Date.now()};scanKeys.forEach(k=>c[k]=String(x[k]||'').trim());c.scanImportedAt=c.updated;c.scanSnapshot=JSON.stringify(c);records.push(c);accepted.push(x)}if(!records.length){scanMessage('No cards added: possible duplicates or missing identity.');return {added:0,duplicates:items.length};}await tx('readwrite',s=>records.forEach(c=>s.add(c)));lastBatch21={batch,ids:records.map(c=>c.id),items:accepted};try{localStorage.setItem('vaultLastBatch21',JSON.stringify({batch,ids:lastBatch21.ids}))}catch{}scanItems=scanItems.filter(x=>!accepted.includes(x));await refresh();drawScan();renderScan();await saveDraft();summary21();scanMessage(`${records.length} cards added. ${scanItems.length} awaiting review.`);return {added:records.length,duplicates:items.length-records.length}}catch(e){scanMessage('Import failed: '+e.message);return {added:0,error:e.message}}finally{if(ownBusy)scanBusy=false}}
async function identify21(){if(scanBusy||!scanItems.length)return;scanBusy=true;stopRequested21=false;detected21=scanItems.length;let worker;let error='';try{for(const x of scanItems){if(x.rect?.[2]>x.rect?.[3]&&!x.upright22){x.photo=await rotate21(x.photo, -1);x.upright22=true;}}queueDraft();if($('autoAI21').checked&&$('visionEndpoint').value&&$('visionKey').value){scanBusy=false;await visionIdentify();scanBusy=true;}if(stopRequested21)return;for(const x of scanItems){const ref=reference23(x,scanRefs);if(ref)for(const k of scanKeys)if(k!=='serial'&&k!=='parallel'&&!x[k]&&ref[k])x[k]=ref[k];}queueDraft();if(!window.Tesseract)await timeout21(loadScanScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js'),20000,'OCR library timed out');worker=await timeout21(Tesseract.createWorker('eng'),45000,'OCR initialization timed out');for(let i=0;i<scanItems.length&&!stopRequested21;i++){const x=scanItems[i];if(x.approved)continue;scanMessage(`Identifying ${i+1}/${scanItems.length}…`);const r=await timeout21(worker.recognize(x.photo),25000,'OCR timed out');x.ocr=r.data.text.trim();if(x.rect?.[2]>x.rect?.[3]){const rotated=await rotate21(x.photo,x.upright22?2:1);const rr=await timeout21(worker.recognize(rotated),25000,'Rotated OCR timed out');if(rr.data.confidence>r.data.confidence){x.photo=rotated;x.ocr=rr.data.text.trim()}}const ref=strongSuggestion(x,scanRefs,$('refFocus').value)||reference23(x,scanRefs);if(ref)for(const k of scanKeys)if(k!=='serial'&&k!=='parallel'&&!x[k]&&ref[k])x[k]=ref[k];queueDraft();await new Promise(r=>setTimeout(r,0))}}catch(e){error=e.message}finally{if(worker)try{await timeout21(worker.terminate(),3000,'Termination timed out')}catch{}scanBusy=false}if(!stopRequested21&&$('autoImport21').checked){const exact=scanItems.filter(x=>exact21(x,scanRefs));await import21(exact,true)}renderScan();summary21();scanMessage(`${stopRequested21?'Stopped':error?'OCR unavailable: '+error:'Identification finished'}. ${scanItems.length} cards awaiting review. ${!$('visionEndpoint').value||!$('visionKey').value?'Visual AI not connected; open Recognition setup.':''}`);}
$('identify21').onclick=identify21;$('stop21').onclick=()=>{stopRequested21=true;scanMessage('Stopping after current recognition step…')};
$('undo21').onclick=async()=>{if(scanBusy)return;let b=lastBatch21;try{b=b||JSON.parse(localStorage.getItem('vaultLastBatch21')||'null')}catch{}if(!b)return scanMessage('No recent scan import to undo.');if(!confirm('Undo the last scan import? Edited cards will be retained.'))return;scanBusy=true;try{const current=await readAll(),eligible=current.filter(c=>b.ids.includes(c.id)&&c.scanBatch===b.batch&&!c.valuation&&!c.resalePlan&&c.value===null&&c.updated===c.scanImportedAt&&JSON.stringify(Object.fromEntries(Object.entries(c).filter(([k])=>k!=='scanSnapshot')))===c.scanSnapshot);if(!eligible.length)return scanMessage('No unchanged cards eligible for undo.');await tx('readwrite',s=>eligible.forEach(c=>s.delete(c.id)));for(const c of eligible){const old=b.items?.find(x=>'scan-'+x.scanId===c.id);scanItems.push(old||{...Object.fromEntries(scanKeys.map(k=>[k,c[k]||''])),photo:c.photo,scanId:c.id.slice(5),approved:false,ocr:''})}lastBatch21=null;localStorage.removeItem('vaultLastBatch21');await refresh();renderScan();await saveDraft();scanMessage(`${eligible.length} cards returned to review.`)}catch(e){scanMessage('Undo failed: '+e.message)}finally{scanBusy=false}};

// v2.6: visible outcome for every bulk import attempt.
$('batchSave').onclick=async()=>{if(scanBusy){alert('Identification is still running. Wait or stop processing before importing.');return;}const selected=scanItems.filter(x=>x.approved&&String(x.player||'').trim());if(!selected.length){alert('No cards ready to add. Choose a match or enter a player name, then approve the card.');return;}const result=await import21(selected,false);alert(result?.error?'Import failed: '+result.error:`${result?.added||0} cards added. ${result?.duplicates||0} skipped (possible duplicates). ${scanItems.length} remain for review.`);};

function reference23(x,refs){const keys=['player','year','brand','set'];if(!keys.every(k=>String(x[k]||'').trim()))return null;const matches=refs.filter(r=>r.source&&keys.every(k=>clean(r[k])===clean(x[k]))&&['number','parallel'].every(k=>!x[k]||clean(x[k])===clean(r[k])));return matches.length===1?matches[0]:null;}

// v2.6 authenticated connectivity check; never equate health with inference.
$('visionTest').onclick=async()=>{if(scanBusy)return alert('Wait for current processing to finish.');try{const u=new URL($('visionEndpoint').value);if(u.protocol!=='https:')throw Error('HTTPS required');const key=$('visionKey').value.trim();if(!key)throw Error('Enter your Worker access key');scanBusy=true;const r=await fetch(u.href,{headers:{Authorization:'Bearer '+key},signal:AbortSignal.timeout(10000)});const j=await r.json();if(!r.ok||j.status!=='ok')throw Error(j.error||'HTTP '+r.status);const msg=[24,26].includes(j.protocol)?'Access key accepted; AI binding configured. Test one cropped image to verify recognition.':'Legacy endpoint reachable; access key not verified. Update Worker.';$('visionStatus24').textContent=msg;alert(msg)}catch(e){$('visionStatus24').textContent='Connection failed: '+e.message;alert($('visionStatus24').textContent)}finally{scanBusy=false}};

// v2.6: non-mutating live recognition probe, separate from import.
function probeIdentity25(r){if(!r||typeof r.player!=='string'||!r.player.trim())throw Error('No player identified. Recognition did not pass.');return ['player','year','brand','set','number','parallel'].map(k=>k+': '+(typeof r[k]==='string'&&r[k].trim()?r[k].trim():'Unknown')).join('\n');}
$('visionProbe').onclick=async()=>{if(scanBusy)return alert('Wait for current processing to finish.');const x=scanItems.find(x=>x.photo);if(!x)return alert('Scan a card first.');let u;try{u=new URL($('visionEndpoint').value);if(u.protocol!=='https:')throw Error()}catch{return alert('Enter a valid HTTPS endpoint.')}const key=$('visionKey').value.trim();if(!key)return alert('Enter your Worker access key.');if(!confirm('Send one cropped card to '+u.origin+' for a recognition test? No inventory changes will be made.'))return;scanBusy=true;const status=$('visionStatus24');status.textContent='Testing actual image recognition…';const ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),45000);try{const res=await fetch(u.href,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+key},body:JSON.stringify({image:x.photo,ocr:x.ocr||''}),signal:ctl.signal});const r=await res.json();if(!res.ok)throw Error(r.error||'HTTP '+res.status);const msg='Model returned a player. Verify the identity against the card before trusting it.\n'+probeIdentity25(r);status.textContent=msg;alert(msg)}catch(e){status.textContent='Recognition test failed: '+e.message;alert(status.textContent)}finally{clearTimeout(timer);scanBusy=false}};
